.blog-profile-panel {
    width: 100%;
    max-width: 260px;
    margin-bottom: 18px;
    color: inherit;
}

.blog-profile-panel__top {
    display: flex;
    align-items: center;
    gap: 12px;
}

.blog-profile-panel__avatar-link {
    flex-shrink: 0;
    text-decoration: none;
}

.blog-profile-panel__avatar {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    object-fit: cover;
    display: block;
}

.blog-profile-panel__identity {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.blog-profile-panel__name {
    font-size: 1.08rem;
    font-weight: 700;
    line-height: 1.08;
    overflow-wrap: anywhere;
    color: inherit;
    text-decoration: none;
}

.blog-profile-panel__name:hover {
    color: inherit;
    text-decoration: none;
}

.blog-profile-panel__blog-name {
    font-size: 0.84rem;
    opacity: 0.8;
    line-height: 1.18;
    overflow-wrap: anywhere;
}

.blog-profile-panel__stats {
    display: flex;
    flex-wrap: wrap;
    gap: 2px 10px;
    font-size: 0.92rem;
    line-height: 1.2;
}

.blog-profile-panel__stats strong {
    font-weight: 700;
}

.blog-profile-panel__author-link {
    margin-top: 4px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.92rem;
    font-weight: 600;
    text-decoration: none;
    color: inherit;
    opacity: 0.92;
}

.blog-profile-panel__author-link:hover {
    text-decoration: underline;
    color: inherit;
}

.blog-profile-panel__actions {
    margin-top: 10px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.blog-profile-panel__follow-btn {
    min-width: 88px;
}

.blog-profile-panel__dropdown {
    position: relative;
    overflow: visible !important;
}

.blog-profile-panel__dropdown-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    text-decoration: none;
    color: inherit;
}

.blog-profile-panel__dropdown-toggle::after {
    display: none !important;
}

.blog-profile-panel .blog-user-dropdown-menu {
    min-width: 220px;
    z-index: 9999;
}

.blog-profile-panel__note {
    margin-top: 10px;
    font-size: 0.84rem;
    opacity: 0.82;
    line-height: 1.3;
}

.blog-profile-panel--gradient .blog-profile-panel__name,
.blog-profile-panel--gradient .blog-profile-panel__blog-name,
.blog-profile-panel--gradient .blog-profile-panel__stats,
.blog-profile-panel--gradient .blog-profile-panel__dropdown-toggle {
    text-shadow: 0 2px 10px rgba(0, 0, 0, 0.28);
}

.blog-profile-panel--gradient .blog-profile-panel__avatar {
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.18);
}

@media (max-width: 991.98px) {
    .blog-profile-panel {
        max-width: none;
    }
}

